using namespace std;

typedef long long ll;

struct step {
	ll value; int cost;
	bool operator<(const step &other) const {
		return other.cost < cost;
	}
};

set<ll> visitedNodes;

bool isVisited(ll c) {
	return visitedNodes.find(c) != visitedNodes.end();
}

step computeUupper(ll n){
	ll res = 0;
	int digits = 0;
	while(res < n){
		res = res * 10 + 1;
		digits++;
	}
	return {res, digits};
}

step computeUpper(ll n){
	ll res = 0;
	int digits = 0;
	while(res * 10 + 1 <= n){
		res = res * 10 + 1;
		digits++;
	}
	ll baseRes = res;
	int baseDigits = digits;
	while(res < n){
		res += baseRes;
		digits += baseDigits;
	}
	return {res, digits};
}

step computeLower(ll n){
	ll res = 0;
	int digits = 0;
	while(res * 10 + 1 <= n){
		res = res * 10 + 1;
		digits++;
	}
	ll baseRes = res;
	int baseDigits = digits;
	while(res + baseRes <= n){
		res += baseRes;
		digits += baseDigits;
	}
	return {res, digits};
}

int main() {
	ll n;
	cin >> n;

