import java.util.*;
import java.io.*;

public class Main {
    static class Step implements Comparable<Step> {
        long value;
        int cost;

        Step(long value, int cost) {
            this.value = value;
            this.cost = cost;
        }

        @Override
        public int compareTo(Step other) {
            // PriorityQueue in Java is a min-heap, so to mimic the C++ code's behavior,
            // we need to compare such that the step with the larger cost is considered "less".
            // But since the C++ code uses a custom operator< that returns true if other.cost < cost,
            // it effectively makes the priority queue a max-heap based on cost.
            // To replicate that, we invert the comparison.
            return Integer.compare(other.cost, this.cost);
        }
    }

    static Set<Long> visitedNodes = new HashSet<>();

    static boolean isVisited(long c) {
        return visitedNodes.contains(c);
    }

    static Step computeUupper(long n) {
        long res = 0;
        int digits = 0;
        while (res < n) {
            res = res * 10 + 1;
            digits++;
        }
        return new Step(res, digits);
    }

    static Step computeUpper(long n) {
        long res = 0;
        int digits = 0;
        while (res * 10 + 1 <= n) {
            res = res * 10 + 1;
            digits++;
        }
        long baseRes = res;
        int baseDigits = digits;
        while (res < n) {
            res += baseRes;
            digits += baseDigits;
        }
        return new Step(res, digits);
    }

    static Step computeLower(long n) {
        long res = 0;
        int digits = 0;
        while (res * 10 + 1 <= n) {
            res = res * 10 + 1;
            digits++;
        }
        long baseRes = res;
        int baseDigits = digits;
        while (res + baseRes <= n) {
            res += baseRes;
            digits += baseDigits;
        }
        return new Step(res, digits);
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        long n = Long.parseLong(br.readLine());

        PriorityQueue<Step> queue = new PriorityQueue<>();
        queue.add(new Step(n, 0));

        while (queue.peek().value != 0) {
            Step current = queue.poll();
            long currentVal = current.value;
            int currentCost = current.cost;

            if (isVisited(currentVal))
                continue;
            visitedNodes.add(currentVal);

            for (Step s : Arrays.asList(computeLower(currentVal), computeUpper(currentVal), computeUupper(currentVal))) {
                s.cost += currentCost;
                s.value = Math.abs(currentVal - s.value);
                queue.add(s);
            }
        }

        System.out.println(queue.peek().cost);
    }
}
